def test_r7_axes_has_forecast_line():
    # The plotted data must include the 7 forecast points.
    df = _make_df()
    forecasts, ax = task_func(df)
    plotted = np.concatenate(
        [np.asarray(line.get_ydata(), dtype=float) for line in ax.lines]
    )
    for value in forecasts:
        assert np.any(np.isclose(plotted, value, atol=1e-6))

